import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.C51MRPOx.js";const c=JSON.parse('{"title":"身份与系统提示词","description":"","frontmatter":{},"headers":[],"relativePath":"智能体设计/身份与系统提示词.md","filePath":"智能体设计/身份与系统提示词.md","lastUpdated":null}'),l={name:"智能体设计/身份与系统提示词.md"};function o(h,t,i,n,p,_){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="身份与系统提示词" tabindex="-1">身份与系统提示词 <a class="header-anchor" href="#身份与系统提示词" aria-label="Permalink to &quot;身份与系统提示词&quot;">​</a></h1><p>系统提示词是运行时在每一轮开始时拼出来的自我说明：你是谁、在帮谁、这一轮该怎么做事。人格不在模型权重里——换一份说明，同一个模型就会换一种说话方式和底线。</p><p>这份说明要短、要稳定、要每轮都在。它不是记忆库，也不是技能手册，那些内容有自己的入口，按这一轮的需要再取。身份层一旦写长，模型会把操作细则当成性格，也会把过期的事实当成永远成立的人设。</p><h2 id="拆开再组装" tabindex="-1">拆开再组装 <a class="header-anchor" href="#拆开再组装" aria-label="Permalink to &quot;拆开再组装&quot;">​</a></h2><p>身份不要写成一大段随手追加的文字。运行时从几份职责不同的材料组装，每一份只回答一个问题：</p><table tabindex="0"><thead><tr><th>材料</th><th>回答的问题</th><th>内容示例</th></tr></thead><tbody><tr><td>性格与底线</td><td>你是什么样的人</td><td>语气、称呼习惯、能做和不能做的事；例如先答再补充、不替用户做未确认的对外承诺</td></tr><tr><td>名字与角色</td><td>你叫什么、此刻扮演什么</td><td>名字、角色、使用的语言；接待设备还带场景标识——通用交谈、迎宾、点单是不同的角色</td></tr><tr><td>服务对象</td><td>你在帮谁</td><td>当前用户、已确认的稳定偏好（称呼、常用语言、明确说过的忌口）；刚发生的闲聊不写进这里</td></tr><tr><td>操作手册</td><td>工作步骤，不是性格</td><td>会话怎么开始、工具和技能在什么时机去读、什么情况必须停下来问人</td></tr></tbody></table><p>组装发生在运行时，不发生在模型内部。一轮开始时，运行时按当前场景读出这几份材料，拼成系统提示词的身份段，再附上本轮允许使用的工具名单；模型只看见拼好的结果。</p><p>材料通常是工作区里的几份文本。运行时在首次启动时放好模板，之后可以人工修改，也允许模型在对话中改「服务对象」和「长期偏好」那一份。性格与底线、操作手册的修改权应收紧：模型可以提议，落盘前要有明确指令，避免一轮闲聊改写底线。</p><h2 id="按场景注册-而不是换进程" tabindex="-1">按场景注册，而不是换进程 <a class="header-anchor" href="#按场景注册-而不是换进程" aria-label="Permalink to &quot;按场景注册，而不是换进程&quot;">​</a></h2><p>同一套运行时可以同时服务几种场景。每种场景在启动时注册两样东西：一份身份、一张这个场景允许的执行图。连接建立时带来场景标识，运行时取出对应的身份和图。</p><ul><li>点单场景的系统提示词里有菜单角色和确认订单的步骤，没有迎宾场景的导览话术；</li><li>迎宾场景不会拿到点单专用的节点；</li><li>人设文案、可用表情和动作的词表，跟场景走，不跟进程走。</li></ul><p>新增一种场景，是新增一份注册，而不是再部署一个进程。身份文件和图的节点名单一起注册，避免「提示词答应了做某件事，图里却没有对应节点」。</p><h2 id="身份层保持短" tabindex="-1">身份层保持短 <a class="header-anchor" href="#身份层保持短" aria-label="Permalink to &quot;身份层保持短&quot;">​</a></h2><p>下面三类内容经常被误放进系统提示词。它们一旦放进去，每一轮都会重复发送，并且会挤占这一轮真正要处理的话：</p><table tabindex="0"><thead><tr><th>不该放的</th><th>正确做法</th></tr></thead><tbody><tr><td>整库记忆</td><td>身份段最多写一句「回答涉及既往事实时，先去检索」；检索到的内容由运行时放进本轮上下文，不写进人设</td></tr><tr><td>全部技能的步骤</td><td>只保留技能名称、一句话适用时机和「用到时再读正文」的约定，操作步骤留在技能自己的文件里</td></tr><tr><td>领域手册</td><td>商品说明、规章制度、长篇问答属于可检索资料；身份段写明「遇到这类问题去检索」，不粘贴手册全文</td></tr></tbody></table><p>身份段适合放的，是换一轮也不会变的规则：我是谁、我在哪种场景、我不能越过的线、我该去哪里取记忆和技能。会变的事实、会很长的步骤、只在某些问题里才用到的资料，都留在身份外面。</p>',16)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
